import { useState, useEffect, useCallback } from "react";
import { db, firebaseConfigured } from "./firebase";
import {
  collection, addDoc, deleteDoc, doc,
  query, orderBy, onSnapshot, serverTimestamp,
} from "firebase/firestore";

const fmt = (ts) =>
  ts?.toDate
    ? ts.toDate().toLocaleString("es", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })
    : "…";

export default function TeacherPortal({ embedded = false }) {
  const [teacherName, setTeacherName] = useState(
    () => localStorage.getItem("teacherName") || ""
  );
  const [studentCode, setStudentCode] = useState("");
  const [noteText,    setNoteText]    = useState("");
  const [notes,       setNotes]       = useState([]);
  const [sending,     setSending]     = useState(false);
  const [error,       setError]       = useState("");

  useEffect(() => {
    if (teacherName) localStorage.setItem("teacherName", teacherName);
  }, [teacherName]);

  // Live listener for the selected student's notes
  const loadStudentNotes = useCallback((code) => {
    if (!db || code.length < 6) return;
    const q = query(
      collection(db, "notes", code, "messages"),
      orderBy("createdAt", "desc")
    );
    return onSnapshot(q,
      (snap) => setNotes(snap.docs.map((d) => ({ id: d.id, ...d.data() }))),
      () => setError("Error al cargar notas — revisa la conexión")
    );
  }, []);

  useEffect(() => {
    setNotes([]);
    setError("");
    if (studentCode.length < 6) return;
    const unsub = loadStudentNotes(studentCode);
    return () => unsub?.();
  }, [studentCode, loadStudentNotes]);

  const sendNote = async () => {
    if (!db || !teacherName.trim() || studentCode.length < 6 || !noteText.trim()) return;
    setSending(true);
    setError("");
    try {
      await addDoc(collection(db, "notes", studentCode, "messages"), {
        text:      noteText.trim(),
        teacher:   teacherName.trim(),
        createdAt: serverTimestamp(),
      });
      setNoteText("");
    } catch {
      setError("Error al enviar la nota. Revisa tu conexión.");
    }
    setSending(false);
  };

  const deleteNote = async (noteId) => {
    if (!db) return;
    try {
      await deleteDoc(doc(db, "notes", studentCode, "messages", noteId));
    } catch {
      setError("No se pudo eliminar la nota.");
    }
  };

  const ready = firebaseConfigured && teacherName.trim() && studentCode.length === 6;

  const inner = (
    <div style={{ maxWidth: embedded ? "none" : 500, margin: "0 auto" }}>

      {/* ── Header (solo en standalone) ── */}
      {!embedded && (
        <div style={{ textAlign: "center", marginBottom: 28 }}>
          <div style={{ fontSize: 40, marginBottom: 6 }}>👨‍🏫</div>
          <div style={{ fontFamily: "'Playfair Display', serif", fontSize: 24, fontWeight: 900 }}>
            Portal del Maestro
          </div>
          <div style={{ color: "#6b8f6b", fontSize: 12, marginTop: 4, letterSpacing: 2, textTransform: "uppercase" }}>
            Práctica Musical
          </div>
        </div>
      )}

        {/* ── Firebase not configured ── */}
        {!firebaseConfigured && (
          <div style={{ background: "#c0504d22", border: "1px solid #c0504d", borderRadius: 12, padding: 16, marginBottom: 20, color: "#e8a8a8", fontSize: 13, lineHeight: 1.6 }}>
            <strong>Firebase no está configurado.</strong><br />
            Crea un archivo <code>.env.local</code> con las variables de Firebase y redeploya la app.
          </div>
        )}

        {/* ── Teacher name ── */}
        <div style={{ marginBottom: 14 }}>
          <label style={{ color: "#8fbc8f", fontSize: 11, textTransform: "uppercase", letterSpacing: 1.5, display: "block", marginBottom: 6 }}>
            Tu nombre
          </label>
          <input
            value={teacherName}
            onChange={(e) => setTeacherName(e.target.value)}
            placeholder="Ej: Profe Rodolfo"
            style={inputStyle}
          />
        </div>

        {/* ── Student code ── */}
        <div style={{ marginBottom: 24 }}>
          <label style={{ color: "#8fbc8f", fontSize: 11, textTransform: "uppercase", letterSpacing: 1.5, display: "block", marginBottom: 6 }}>
            Código del estudiante
          </label>
          <input
            value={studentCode}
            onChange={(e) => setStudentCode(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 6))}
            placeholder="Ej: AB3K7P"
            maxLength={6}
            style={{ ...inputStyle, fontSize: 22, fontWeight: 700, letterSpacing: 6, fontFamily: "monospace", textAlign: "center" }}
          />
          {studentCode.length > 0 && studentCode.length < 6 && (
            <div style={{ color: "#6b8f6b", fontSize: 12, marginTop: 4 }}>
              {6 - studentCode.length} caracteres más
            </div>
          )}
        </div>

        {/* ── Compose note ── */}
        {studentCode.length === 6 && (
          <div style={{ background: "#2d4a35", borderRadius: 16, padding: 18, marginBottom: 24 }}>
            <label style={{ color: "#8fbc8f", fontSize: 11, textTransform: "uppercase", letterSpacing: 1.5, display: "block", marginBottom: 10 }}>
              Nueva nota para {studentCode}
            </label>
            <textarea
              value={noteText}
              onChange={(e) => setNoteText(e.target.value)}
              placeholder="Ej: Trabaja más lento la escala de Re mayor, prestando atención a la afinación en el fa#. Prueba con el metrónomo a ♩=60..."
              rows={4}
              style={{ ...inputStyle, background: "#1a2e22", resize: "vertical" }}
            />
            <button
              onClick={sendNote}
              disabled={sending || !ready || !noteText.trim()}
              style={{
                marginTop: 12, width: "100%", padding: "13px",
                background: sending || !noteText.trim() ? "#2d4a35" : "#4a7c59",
                color: "#e8e4d8", border: "none", borderRadius: 10,
                cursor: sending || !noteText.trim() ? "default" : "pointer",
                fontWeight: 700, fontSize: 15,
                opacity: !ready || !noteText.trim() ? 0.5 : 1,
                transition: "all 0.2s",
              }}
            >
              {sending ? "Enviando…" : "📨 Enviar nota"}
            </button>
          </div>
        )}

        {/* ── Error ── */}
        {error && (
          <div style={{ color: "#c0504d", fontSize: 13, marginBottom: 12, textAlign: "center" }}>
            {error}
          </div>
        )}

        {/* ── Notes sent to this student ── */}
        {studentCode.length === 6 && notes.length === 0 && (
          <div style={{ textAlign: "center", color: "#6b8f6b", fontSize: 14, padding: "24px 0" }}>
            Aún no hay notas enviadas a <strong>{studentCode}</strong>
          </div>
        )}

        {notes.length > 0 && (
          <div>
            <div style={{ color: "#6b8f6b", fontSize: 11, textTransform: "uppercase", letterSpacing: 2, marginBottom: 12 }}>
              Notas enviadas · {studentCode}
            </div>
            <div style={{ display: "grid", gap: 10 }}>
              {notes.map((n) => (
                <div key={n.id} style={{ background: "#2d4a35", borderRadius: 14, padding: "14px 16px" }}>
                  <div style={{ fontSize: 14, color: "#e8e4d8", lineHeight: 1.6, marginBottom: 10, whiteSpace: "pre-wrap" }}>
                    {n.text}
                  </div>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <div>
                      <span style={{ color: "#4a7c59", fontSize: 12, fontWeight: 700 }}>{n.teacher}</span>
                      <span style={{ color: "#6b8f6b", fontSize: 11, marginLeft: 10 }}>{fmt(n.createdAt)}</span>
                    </div>
                    <button
                      onClick={() => deleteNote(n.id)}
                      style={{ background: "none", border: "none", color: "#c0504d", cursor: "pointer", fontSize: 18, lineHeight: 1, padding: "0 4px" }}
                      title="Eliminar nota"
                    >×</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {!embedded && (
          <div style={{ marginTop: 32, textAlign: "center", color: "#3d5e45", fontSize: 11 }}>
            Esta URL es solo para maestros.<br />
            Los estudiantes usan la app normal.
          </div>
        )}
      </div>
  );

  return embedded ? inner : (
    <div style={{ minHeight: "100vh", background: "#1a2e22", color: "#e8e4d8", fontFamily: "'Lora', Georgia, serif", padding: "24px 16px" }}>
      {inner}
    </div>
  );
}

const inputStyle = {
  width: "100%", padding: "10px 14px",
  borderRadius: 10, border: "1px solid #4a7c59",
  background: "#2d4a35", color: "#e8e4d8",
  fontSize: 15, outline: "none",
  fontFamily: "'Lora', Georgia, serif",
};
