// ─── Stroke helpers ───────────────────────────────────────────────────────────
function drawStroke(ctx, stroke) {
  if (!stroke.points || stroke.points.length < 2) return;
  ctx.save();
  ctx.globalCompositeOperation = stroke.tool === "eraser" ? "destination-out" : "source-over";
  ctx.strokeStyle = stroke.color;
  ctx.lineWidth   = stroke.width;
  ctx.lineCap     = "round";
  ctx.lineJoin    = "round";
  ctx.globalAlpha = stroke.tool === "highlight" ? 0.45 : 1;
  ctx.beginPath();
  ctx.moveTo(stroke.points[0].x, stroke.points[0].y);
  for (let i = 1; i < stroke.points.length; i++) {
    const mid = {
      x: (stroke.points[i - 1].x + stroke.points[i].x) / 2,
      y: (stroke.points[i - 1].y + stroke.points[i].y) / 2,
    };
    ctx.quadraticCurveTo(stroke.points[i - 1].x, stroke.points[i - 1].y, mid.x, mid.y);
  }
  ctx.stroke();
  ctx.restore();
}

function redrawAll(canvas, strokes) {
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  strokes.forEach((s) => drawStroke(ctx, s));
}

const ptDist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

// ─── ScoreRecorder: audio + video ────────────────────────────────────────────
function ScoreRecorder({ lang = "es" }) {
  const L = {
    es: {
      audio: "🎙 Audio", video: "📹 Video",
      rec: "● Grabar", stop: "⏹ Detener",
      saved: "Grabaciones", dl: "⬇ Descargar",
      empty: "Sin grabaciones aún",
      permErr: "No se pudo acceder al micrófono/cámara.",
    },
    en: {
      audio: "🎙 Audio", video: "📹 Video",
      rec: "● Record", stop: "⏹ Stop",
      saved: "Recordings", dl: "⬇ Download",
      empty: "No recordings yet",
      permErr: "Could not access microphone/camera.",
    },
  }[lang] || {};

  const [mode,         setMode]         = useState("audio");
  const [recording,    setRecording]    = useState(false);
  const [elapsed,      setElapsed]      = useState(0);
  const [recordings,   setRecordings]   = useState([]);
  const [open,         setOpen]         = useState(false);
  const [mediaRecorder,setMediaRecorder]= useState(null);
  const videoPreviewRef = useRef(null);
  const chunksRef       = useRef([]);
  const timerRef        = useRef(null);

  const fmt = (s) => `${String(Math.floor(s / 60)).padStart(2,"0")}:${String(s % 60).padStart(2,"0")}`;

  const startRec = async () => {
    try {
      const constraints = mode === "video"
        ? { video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } }, audio: { echoCancellation: false, noiseSuppression: false } }
        : { audio: { echoCancellation: false, noiseSuppression: false } };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      if (mode === "video" && videoPreviewRef.current) videoPreviewRef.current.srcObject = stream;
      chunksRef.current = [];
      const mimeType = mode === "video"
        ? (MediaRecorder.isTypeSupported("video/mp4;codecs=h264,aac") ? "video/mp4;codecs=h264,aac" : "video/webm;codecs=vp9,opus")
        : (MediaRecorder.isTypeSupported("audio/mp4;codecs=aac") ? "audio/mp4;codecs=aac" : "audio/webm;codecs=opus");
      const mr = new MediaRecorder(stream, { mimeType });
      mr.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      mr.onstop = () => {
        stream.getTracks().forEach((t) => t.stop());
        if (videoPreviewRef.current) videoPreviewRef.current.srcObject = null;
        const blob = new Blob(chunksRef.current, { type: mimeType });
        const url  = URL.createObjectURL(blob);
        const ext  = mode === "video" ? (mimeType.includes("mp4") ? "mp4" : "webm") : (mimeType.includes("mp4") ? "m4a" : "webm");
        setRecordings((r) => [{ id: Date.now(), url, ext, mode, label: new Date().toLocaleTimeString() }, ...r]);
        setOpen(true);
      };
      mr.start(1000);
      setMediaRecorder(mr);
      setRecording(true);
      setElapsed(0);
      timerRef.current = setInterval(() => setElapsed((e) => e + 1), 1000);
    } catch { alert(L.permErr); }
  };

  const stopRec = () => {
    mediaRecorder?.stop();
    setMediaRecorder(null);
    setRecording(false);
    clearInterval(timerRef.current);
  };

  useEffect(() => () => clearInterval(timerRef.current), []);

  return (
    <div style={{ background: "#1a2e22", borderRadius: 14, overflow: "hidden", marginTop: 10 }}>
      {/* Header bar */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 14px" }}>
        {/* Mode toggle */}
        {!recording && (
          <div style={{ display: "flex", gap: 4 }}>
            {["audio","video"].map((m) => (
              <button key={m} onClick={() => setMode(m)}
                style={{ padding: "5px 10px", background: mode === m ? "#4a7c59" : "#2d4a35", color: "#e8e4d8", border: "none", borderRadius: 7, cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
                {m === "audio" ? L.audio : L.video}
              </button>
            ))}
          </div>
        )}

        {/* Timer when recording */}
        {recording && (
          <span style={{ color: "#c0504d", fontWeight: 700, fontSize: 14, display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#c0504d", display: "inline-block", animation: "pulse 1s infinite" }} />
            REC {fmt(elapsed)}
          </span>
        )}

        <div style={{ flex: 1 }} />

        {/* Record / Stop */}
        <button onClick={recording ? stopRec : startRec}
          style={{ background: recording ? "#c0504d" : "#4a7c59", color: "#fff", border: "none", borderRadius: 8, padding: "6px 14px", cursor: "pointer", fontWeight: 700, fontSize: 13 }}>
          {recording ? L.stop : L.rec}
        </button>

        {/* Saved count toggle */}
        {recordings.length > 0 && (
          <button onClick={() => setOpen((o) => !o)}
            style={{ background: "#2d4a35", color: "#8fbc8f", border: "1px solid #4a7c59", borderRadius: 8, padding: "5px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
            {L.saved} {recordings.length} {open ? "▲" : "▼"}
          </button>
        )}
      </div>

      {/* Video preview */}
      {mode === "video" && recording && (
        <div style={{ padding: "0 14px 10px" }}>
          <video ref={videoPreviewRef} autoPlay muted playsInline
            style={{ width: "100%", maxHeight: 160, borderRadius: 8, background: "#000", objectFit: "cover" }} />
        </div>
      )}

      {/* Recordings list */}
      {open && recordings.length > 0 && (
        <div style={{ padding: "0 14px 14px", display: "grid", gap: 8 }}>
          {recordings.map((r) => (
            <div key={r.id} style={{ background: "#2d4a35", borderRadius: 10, padding: 10 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                <span style={{ color: "#8fbc8f", fontSize: 12 }}>
                  {r.mode === "video" ? "📹" : "🎙"} {r.label}
                </span>
                <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                  <a href={r.url} download={`partitura-${r.id}.${r.ext}`}
                    style={{ color: "#4a7c59", fontSize: 12, fontWeight: 700, textDecoration: "none" }}>
                    {L.dl} .{r.ext}
                  </a>
                  <button onClick={() => setRecordings((rs) => rs.filter((x) => x.id !== r.id))}
                    style={{ background: "none", border: "none", color: "#c0504d", cursor: "pointer", fontSize: 16, lineHeight: 1, padding: 0 }}>×</button>
                </div>
              </div>
              {r.mode === "video"
                ? <video src={r.url} controls playsInline style={{ width: "100%", borderRadius: 7, background: "#000", maxHeight: 200 }} />
                : <audio src={r.url} controls style={{ width: "100%", height: 32 }} />}
            </div>
          ))}
        </div>
      )}
      <style>{`@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.3}}`}</style>
    </div>
  );
}

// ─── Main ScoreViewer ─────────────────────────────────────────────────────────
export default function ScoreViewer({ lang = "es", onNavChange = () => {} }) {
  const S = {
    es: {
      title: "🎼 Partituras", openLocal: "📁 Abrir desde dispositivo",
      openDrive: "☁️ Google Drive", noScore: "Abre una partitura para comenzar",
      page: "Pág.", of: "de", width: "Grosor", undo: "Deshacer", redo: "Rehacer",
      clearPage: "Limpiar página", loadingPdf: "Cargando PDF...",
      noGapi: "Configura REACT_APP_GDRIVE_CLIENT_ID para usar Drive",
      driveConnect: "Conectar Drive", fileName: "Archivo:",
      annotSaved: "Guardado", hideTools: "Ocultar", showTools: "Herramientas",
    },
    en: {
      title: "🎼 Sheet Music", openLocal: "📁 Open from device",
      openDrive: "☁️ Google Drive", noScore: "Open a score to start annotating",
      page: "Pg.", of: "of", width: "Size", undo: "Undo", redo: "Redo",
      clearPage: "Clear page", loadingPdf: "Loading PDF...",
      noGapi: "Set REACT_APP_GDRIVE_CLIENT_ID to use Drive",
      driveConnect: "Connect Drive", fileName: "File:",
      annotSaved: "Saved", hideTools: "Hide", showTools: "Tools",
    },
  }[lang] || {};

  const [pdfDoc,        setPdfDoc]        = useState(null);
  const [pageNum,       setPageNum]       = useState(1);
  const [totalPages,    setTotalPages]    = useState(0);
  const [zoom,          setZoom]          = useState(1.5);
  const [tool,          setTool]          = useState("select");
  const [color,         setColor]         = useState("#1a1a1a");
  const [lineWidth,     setLineWidth]     = useState(3);
  const [strokes,       setStrokes]       = useState({});
  const [undoStack,     setUndoStack]     = useState([]);
  const [redoStack,     setRedoStack]     = useState([]);
  const [drawing,       setDrawing]       = useState(false);
  const [currentStroke, setCurrentStroke] = useState(null);
  const [docId,         setDocId]         = useState(null);
  const [fileName,      setFileName]      = useState("");
  const [loading,       setLoading]       = useState(false);
  const [gapiReady,     setGapiReady]     = useState(false);
  const [gapiSignedIn,  setGapiSignedIn]  = useState(false);
  const [saveMsg,       setSaveMsg]       = useState("");
  const [toolbarVisible,setToolbarVisible]= useState(true);
  const [showImslp,     setShowImslp]     = useState(false);
  const [imslpQuery,    setImslpQuery]    = useState("");
  const [imslpResults,  setImslpResults]  = useState([]);
  const [imslpLoading,  setImslpLoading]  = useState(false);

  const pdfCanvasRef        = useRef(null);
  const annotCanvasRef      = useRef(null);
  const fileInputRef        = useRef(null);
  const canvasContainerRef  = useRef(null);
  const renderingRef        = useRef(false);
  const pinchRef            = useRef({ active: false, startDist: 0, startZoom: 1 });
  const activePtrRef        = useRef(new Map());
  const zoomRef             = useRef(zoom);

  // Auto-fit zoom to container width
  const fitToWidth = useCallback((doc, pNum = 1) => {
    if (!canvasContainerRef.current) return;
    doc.getPage(pNum).then((page) => {
      const naturalW  = page.getViewport({ scale: 1 }).width;
      const available = canvasContainerRef.current.clientWidth - 4;
      setZoom(+(available / naturalW).toFixed(2));
    });
  }, []);

  // Keep zoomRef in sync for pinch handler (avoids stale closure)
  useEffect(() => { zoomRef.current = zoom; }, [zoom]);

  // Re-fit on window resize
  useEffect(() => {
    if (!pdfDoc) return;
    const handler = () => fitToWidth(pdfDoc, pageNum);
    window.addEventListener("resize", handler);
    return () => window.removeEventListener("resize", handler);
  }, [pdfDoc, pageNum, fitToWidth]);

  const strokeKey = `${docId}-${pageNum}`;

  // ── PDF.js ─────────────────────────────────────────────────────────────────
  useEffect(() => {
    if (window.pdfjsLib) return;
    const script = document.createElement("script");
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
    script.onload = () => {
      window.pdfjsLib.GlobalWorkerOptions.workerSrc =
        "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
    };
    document.head.appendChild(script);
  }, []);

  // ── Google API ─────────────────────────────────────────────────────────────
  useEffect(() => {
    if (!GDRIVE_CLIENT_ID) return;
    const script = document.createElement("script");
    script.src = "https://apis.google.com/js/api.js";
    script.onload = () => {
      window.gapi.load("client:auth2:picker", () => {
        window.gapi.client
          .init({ apiKey: GDRIVE_API_KEY, clientId: GDRIVE_CLIENT_ID, discoveryDocs: [GDRIVE_DISCOVERY], scope: GDRIVE_SCOPE })
          .then(() => {
            setGapiReady(true);
            setGapiSignedIn(window.gapi.auth2.getAuthInstance().isSignedIn.get());
            window.gapi.auth2.getAuthInstance().isSignedIn.listen(setGapiSignedIn);
          });
      });
    };
    document.head.appendChild(script);
  }, []);

  // ── Annotations persistence ────────────────────────────────────────────────
  useEffect(() => {
    if (!docId) return;
    try { setStrokes(JSON.parse(localStorage.getItem(`annot-${docId}`) || "{}")); } catch {}
  }, [docId]);

  useEffect(() => {
    if (!docId || Object.keys(strokes).length === 0) return;
    try {
      localStorage.setItem(`annot-${docId}`, JSON.stringify(strokes));
      setSaveMsg(S.annotSaved);
      const t = setTimeout(() => setSaveMsg(""), 1500);
      return () => clearTimeout(t);
    } catch {}
  }, [strokes, docId, S.annotSaved]);

  // ── Render PDF page ────────────────────────────────────────────────────────
  useEffect(() => {
    if (!pdfDoc || !pdfCanvasRef.current || renderingRef.current) return;
    renderingRef.current = true;
    pdfDoc.getPage(pageNum).then((page) => {
      const viewport = page.getViewport({ scale: zoom });
      const canvas   = pdfCanvasRef.current;
      const annotC   = annotCanvasRef.current;
      if (!canvas || !annotC) { renderingRef.current = false; return; }
      canvas.width  = viewport.width;
      canvas.height = viewport.height;
      annotC.width  = viewport.width;
      annotC.height = viewport.height;
      page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise.then(() => {
        renderingRef.current = false;
        redrawAll(annotC, strokes[strokeKey] || []);
      });
    });
  }, [pdfDoc, pageNum, zoom, strokes, strokeKey]);

  // ── Open local file ────────────────────────────────────────────────────────
  const openLocalFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setLoading(true);
    setFileName(file.name);
    setDocId(`local-${file.name}-${file.size}`);
    const reader = new FileReader();
    reader.onload = (ev) => {
      window.pdfjsLib.getDocument(new Uint8Array(ev.target.result)).promise.then((doc) => {
        setPdfDoc(doc);
        setTotalPages(doc.numPages);
        setPageNum(1);
        setLoading(false);
        fitToWidth(doc, 1);
      });
    };
    reader.readAsArrayBuffer(file);
    e.target.value = "";
  };

  // ── Google Drive picker ────────────────────────────────────────────────────
  const openDrivePicker = () => {
    if (!gapiReady) return;
    if (!gapiSignedIn) { window.gapi.auth2.getAuthInstance().signIn(); return; }
    const token  = window.gapi.auth2.getAuthInstance().currentUser.get().getAuthResponse().access_token;
    const picker = new window.google.picker.PickerBuilder()
      .addView(new window.google.picker.DocsView().setMimeTypes("application/pdf"))
      .setOAuthToken(token).setDeveloperKey(GDRIVE_API_KEY)
      .setCallback((data) => {
        if (data.action === window.google.picker.Action.PICKED) {
          const f = data.docs[0];
          setFileName(f.name); setLoading(true);
          setDocId(`drive-${f.id}`);
          fetch(`https://www.googleapis.com/drive/v3/files/${f.id}?alt=media`, { headers: { Authorization: `Bearer ${token}` } })
            .then((r) => r.arrayBuffer())
            .then((buf) => {
              window.pdfjsLib.getDocument(new Uint8Array(buf)).promise.then((doc) => {
                setPdfDoc(doc); setTotalPages(doc.numPages); setPageNum(1); setLoading(false);
                fitToWidth(doc, 1);
              });
            });
        }
      }).build();
    picker.setVisible(true);
  };

  // ── Pointer drawing ────────────────────────────────────────────────────────
  const getPos = (e, canvas) => {
    const rect   = canvas.getBoundingClientRect();
    const scaleX = canvas.width  / rect.width;
    const scaleY = canvas.height / rect.height;
    const src    = e.touches ? e.touches[0] : e;
    return { x: (src.clientX - rect.left) * scaleX, y: (src.clientY - rect.top) * scaleY };
  };

  const onPointerDown = useCallback((e) => {
    if (!annotCanvasRef.current) return;
    e.preventDefault();
    annotCanvasRef.current.setPointerCapture(e.pointerId);
    activePtrRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    // Two fingers → start pinch-to-zoom, cancel any active stroke
    if (activePtrRef.current.size >= 2) {
      const [p1, p2] = [...activePtrRef.current.values()];
      pinchRef.current = { active: true, startDist: ptDist(p1, p2), startZoom: zoomRef.current };
      setDrawing(false);
      setCurrentStroke(null);
      return;
    }

    if (tool === "select") return;
    setDrawing(true);
    setCurrentStroke({
      tool, points: [getPos(e, annotCanvasRef.current)],
      color: tool === "eraser" ? "#000000" : color,
      width: tool === "eraser" ? lineWidth * 6 : tool === "highlight" ? lineWidth * 4 : lineWidth,
    });
  }, [tool, color, lineWidth]);

  const onPointerMove = useCallback((e) => {
    if (!annotCanvasRef.current) return;
    e.preventDefault();
    activePtrRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    // Pinch-to-zoom
    if (pinchRef.current.active && activePtrRef.current.size >= 2) {
      const [p1, p2] = [...activePtrRef.current.values()];
      const newZoom = Math.min(4, Math.max(0.5, +(pinchRef.current.startZoom * ptDist(p1, p2) / pinchRef.current.startDist).toFixed(2)));
      setZoom(newZoom);
      return;
    }

    if (!drawing || !currentStroke) return;
    const updated = { ...currentStroke, points: [...currentStroke.points, getPos(e, annotCanvasRef.current)] };
    setCurrentStroke(updated);
    redrawAll(annotCanvasRef.current, strokes[strokeKey] || []);
    drawStroke(annotCanvasRef.current.getContext("2d"), updated);
  }, [drawing, currentStroke, strokes, strokeKey]);

  const onPointerUp = useCallback((e) => {
    if (e?.pointerId != null) activePtrRef.current.delete(e.pointerId);
    if (activePtrRef.current.size < 2) pinchRef.current.active = false;
    if (!drawing || !currentStroke) return;
    setDrawing(false);
    const newStrokes = { ...strokes, [strokeKey]: [...(strokes[strokeKey] || []), currentStroke] };
    setStrokes(newStrokes);
    setUndoStack((u) => [...u, strokes]);
    setRedoStack([]);
    setCurrentStroke(null);
  }, [drawing, currentStroke, strokes, strokeKey]);

  const undo = () => {
    if (!undoStack.length) return;
    const prev = undoStack[undoStack.length - 1];
    setRedoStack((r) => [strokes, ...r]);
    setStrokes(prev);
    setUndoStack((u) => u.slice(0, -1));
    if (annotCanvasRef.current) redrawAll(annotCanvasRef.current, prev[strokeKey] || []);
  };

  const redo = () => {
    if (!redoStack.length) return;
    const next = redoStack[0];
    setUndoStack((u) => [...u, strokes]);
    setStrokes(next);
    setRedoStack((r) => r.slice(1));
    if (annotCanvasRef.current) redrawAll(annotCanvasRef.current, next[strokeKey] || []);
  };

  const clearPage = () => {
    setUndoStack((u) => [...u, strokes]);
    setStrokes({ ...strokes, [strokeKey]: [] });
    if (annotCanvasRef.current) {
      const ctx = annotCanvasRef.current.getContext("2d");
      ctx.clearRect(0, 0, annotCanvasRef.current.width, annotCanvasRef.current.height);
    }
  };

  // ── IMSLP search via CORS proxy → MediaWiki API ──────────────────────────
  const searchImslp = useCallback(async (q) => {
    if (!q.trim()) { setImslpResults([]); return; }
    setImslpLoading(true);
    try {
      const apiUrl = `https://imslp.org/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&srlimit=12&srnamespace=0&format=json`;
      const res    = await fetch(`https://corsproxy.io/?${encodeURIComponent(apiUrl)}`);
      const data   = await res.json();
      setImslpResults(data?.query?.search || []);
    } catch { setImslpResults([]); }
    setImslpLoading(false);
  }, []);

  // Signal parent to hide/show its nav bar
  useEffect(() => {
    onNavChange(!!pdfDoc && !toolbarVisible);
  }, [pdfDoc, toolbarVisible, onNavChange]);

  // Debounce search as user types
  const imslpTimerRef = useRef(null);
  const handleImslpInput = (val) => {
    setImslpQuery(val);
    clearTimeout(imslpTimerRef.current);
    imslpTimerRef.current = setTimeout(() => searchImslp(val), 500);
  };

  // ── UI ─────────────────────────────────────────────────────────────────────
  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", gap: 0 }}>

      {/* ── Top bar: oculto cuando hay partitura y toolbar escondido ── */}
      <div style={{
        display: "flex", alignItems: "center", gap: 8, flexShrink: 0,
        maxHeight: (!pdfDoc || toolbarVisible) ? 60 : 0,
        opacity:   (!pdfDoc || toolbarVisible) ? 1  : 0,
        overflow: "hidden",
        padding:   (!pdfDoc || toolbarVisible) ? "8px 0" : 0,
        transition: "max-height 0.25s ease, opacity 0.2s ease, padding 0.25s ease",
      }}>
        <span style={{ fontFamily: "'Playfair Display', serif", color: "#1a2e22", fontSize: 20, fontWeight: 900 }}>{S.title}</span>
        <button onClick={() => fileInputRef.current?.click()}
          style={{ padding: "6px 12px", background: "#1a2e22", color: "#e8e4d8", border: "none", borderRadius: 8, cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
          {S.openLocal}
        </button>
        <input ref={fileInputRef} type="file" accept=".pdf" style={{ display: "none" }} onChange={openLocalFile} />
        {GDRIVE_CLIENT_ID ? (
          <button onClick={openDrivePicker}
            style={{ padding: "6px 12px", background: gapiSignedIn ? "#4a7c59" : "#2d4a35", color: "#e8e4d8", border: "1px solid #4a7c59", borderRadius: 8, cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
            {gapiSignedIn ? S.openDrive : S.driveConnect}
          </button>
        ) : null}
        {fileName && (
          <span style={{ color: "#6b8f6b", fontSize: 11, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {fileName} {saveMsg && <span style={{ color: "#4a7c59" }}>✓</span>}
          </span>
        )}
        {!fileName && <span style={{ flex: 1 }} />}
        <button
          onClick={() => setShowImslp((v) => !v)}
          style={{ padding: "6px 12px", background: showImslp ? "#4a7c59" : "#2d4a35", color: "#e8e4d8", border: "1px solid #4a7c59", borderRadius: 8, cursor: "pointer", fontSize: 12, fontWeight: 700, whiteSpace: "nowrap" }}>
          🔍 IMSLP
        </button>
      </div>

      {/* ── IMSLP search panel ── */}
      <div style={{
        flexShrink: 0, overflow: "hidden",
        maxHeight: showImslp ? 420 : 0,
        opacity:   showImslp ? 1 : 0,
        transition: "max-height 0.3s ease, opacity 0.2s ease",
        marginBottom: showImslp ? 6 : 0,
      }}>
        <div style={{ background: "#1a2e22", borderRadius: 12, padding: 14 }}>
          {/* Search input */}
          <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
            <input
              value={imslpQuery}
              onChange={(e) => handleImslpInput(e.target.value)}
              placeholder={lang === "es" ? "Buscar en IMSLP: compositor, obra..." : "Search IMSLP: composer, piece..."}
              style={{ flex: 1, padding: "9px 12px", borderRadius: 8, border: "1px solid #4a7c59", background: "#2d4a35", color: "#e8e4d8", fontSize: 14, outline: "none" }}
            />
            {imslpLoading && <span style={{ color: "#8fbc8f", alignSelf: "center", fontSize: 13 }}>⏳</span>}
          </div>

          {/* Results */}
          <div style={{ maxHeight: 310, overflowY: "auto", display: "grid", gap: 6 }}>
            {imslpResults.length === 0 && imslpQuery && !imslpLoading && (
              <div style={{ color: "#6b8f6b", fontSize: 13, textAlign: "center", padding: 16 }}>
                {lang === "es" ? "Sin resultados" : "No results"}
              </div>
            )}
            {imslpResults.map((r) => {
              const imslpUrl = `https://imslp.org/wiki/${encodeURIComponent(r.title.replace(/ /g, "_"))}`;
              const clean    = r.title.replace(/\(.*?\)/g, "").trim();
              const composer = r.title.match(/\(([^)]+)\)$/)?.[1] || "";
              return (
                <a key={r.pageid} href={imslpUrl} target="_blank" rel="noreferrer"
                  style={{ display: "block", background: "#2d4a35", borderRadius: 9, padding: "10px 14px", textDecoration: "none", border: "1px solid transparent", transition: "border 0.15s" }}
                  onMouseEnter={(e) => e.currentTarget.style.borderColor = "#4a7c59"}
                  onMouseLeave={(e) => e.currentTarget.style.borderColor = "transparent"}
                >
                  <div style={{ color: "#e8e4d8", fontSize: 13, fontWeight: 700, marginBottom: 2 }}>{clean}</div>
                  {composer && <div style={{ color: "#8fbc8f", fontSize: 11 }}>{composer}</div>}
                  <div style={{ color: "#4a7c59", fontSize: 11, marginTop: 4 }}>→ imslp.org</div>
                </a>
              );
            })}
          </div>

          {imslpResults.length > 0 && (
            <div style={{ color: "#6b8f6b", fontSize: 11, textAlign: "center", marginTop: 10 }}>
              {lang === "es"
                ? "Toca un resultado para ir a IMSLP y descargar el PDF"
                : "Tap a result to open IMSLP and download the PDF"}
            </div>
          )}
        </div>
      </div>

      {/* ── Collapsible toolbar ── */}
      <div style={{
        background: "#1a2e22", borderRadius: 12, overflow: "hidden", flexShrink: 0,
        maxHeight: toolbarVisible ? 200 : 0,
        opacity: toolbarVisible ? 1 : 0,
        transition: "max-height 0.25s ease, opacity 0.2s ease",
        marginBottom: toolbarVisible ? 6 : 0,
      }}>
        <div style={{ padding: "8px 12px", display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          {/* Drawing tools */}
          <div style={{ display: "flex", gap: 5 }}>
            {TOOLS.map((t_) => (
              <button key={t_.id} onClick={() => setTool(t_.id)} title={t_.label}
                style={{ background: tool === t_.id ? "#4a7c59" : "transparent", color: "#e8e4d8", border: "1px solid #4a7c59", borderRadius: 7, padding: "6px 9px", cursor: "pointer", fontSize: 15 }}>
                {t_.icon}
              </button>
            ))}
          </div>

          <div style={{ width: 1, height: 24, background: "#2d4a35" }} />

          {/* Colors */}
          <div style={{ display: "flex", gap: 5, alignItems: "center" }}>
            {COLORS.map((c_) => (
              <button key={c_.value} onClick={() => { setColor(c_.value); if (c_.highlight) setTool("highlight"); else if (tool === "highlight") setTool("pen"); }}
                title={c_.label}
                style={{ width: 20, height: 20, borderRadius: "50%", border: color === c_.value ? "3px solid #fff" : "2px solid #4a7c59", cursor: "pointer", background: c_.highlight ? "#ffd700" : c_.value, padding: 0, flexShrink: 0 }} />
            ))}
          </div>

          <div style={{ width: 1, height: 24, background: "#2d4a35" }} />

          {/* Line width */}
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ color: "#8fbc8f", fontSize: 11 }}>{S.width}</span>
            <input type="range" min={1} max={12} value={lineWidth} onChange={(e) => setLineWidth(+e.target.value)}
              style={{ width: 64, accentColor: "#4a7c59" }} />
            <span style={{ color: "#e8e4d8", fontSize: 12, minWidth: 14 }}>{lineWidth}</span>
          </div>

          <div style={{ width: 1, height: 24, background: "#2d4a35" }} />

          {/* Undo / Redo / Clear */}
          <div style={{ display: "flex", gap: 5 }}>
            <button onClick={undo} disabled={!undoStack.length} title={S.undo}
              style={{ background: "transparent", color: undoStack.length ? "#e8e4d8" : "#4a7c59", border: "1px solid #4a7c59", borderRadius: 7, padding: "5px 9px", cursor: undoStack.length ? "pointer" : "default" }}>↩</button>
            <button onClick={redo} disabled={!redoStack.length} title={S.redo}
              style={{ background: "transparent", color: redoStack.length ? "#e8e4d8" : "#4a7c59", border: "1px solid #4a7c59", borderRadius: 7, padding: "5px 9px", cursor: redoStack.length ? "pointer" : "default" }}>↪</button>
            <button onClick={clearPage} title={S.clearPage}
              style={{ background: "transparent", color: "#c0504d", border: "1px solid #c0504d", borderRadius: 7, padding: "5px 9px", cursor: "pointer" }}>🗑</button>
          </div>

          <div style={{ width: 1, height: 24, background: "#2d4a35" }} />

          {/* Zoom */}
          <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
            <button onClick={() => setZoom((z) => Math.max(0.5, +(z - 0.2).toFixed(1)))}
              style={{ background: "transparent", color: "#8fbc8f", border: "1px solid #4a7c59", borderRadius: 6, padding: "4px 8px", cursor: "pointer" }}>−</button>
            <span style={{ color: "#e8e4d8", fontSize: 12, minWidth: 38, textAlign: "center" }}>{Math.round(zoom * 100)}%</span>
            <button onClick={() => setZoom((z) => Math.min(4, +(z + 0.2).toFixed(1)))}
              style={{ background: "transparent", color: "#8fbc8f", border: "1px solid #4a7c59", borderRadius: 6, padding: "4px 8px", cursor: "pointer" }}>+</button>
          </div>
        </div>
      </div>

      {/* ── Score area (flex-1 = fills all remaining space) ── */}
      {(pdfDoc || loading) && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4, flexShrink: 0, justifyContent: "center" }}>
          <button onClick={() => setPageNum((p) => Math.max(1, p - 1))} disabled={pageNum <= 1}
            style={{ background: pageNum > 1 ? "#4a7c59" : "#2d4a35", color: "#e8e4d8", border: "none", borderRadius: 7, padding: "6px 14px", cursor: pageNum > 1 ? "pointer" : "default", fontWeight: 700 }}>‹</button>
          <span style={{ color: "#2d4a35", fontWeight: 700, fontSize: 13 }}>{S.page} {pageNum} {S.of} {totalPages}</span>
          <button onClick={() => setPageNum((p) => Math.min(totalPages, p + 1))} disabled={pageNum >= totalPages}
            style={{ background: pageNum < totalPages ? "#4a7c59" : "#2d4a35", color: "#e8e4d8", border: "none", borderRadius: 7, padding: "6px 14px", cursor: pageNum < totalPages ? "pointer" : "default", fontWeight: 700 }}>›</button>
        </div>
      )}

      {loading && (
        <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", color: "#8fbc8f", fontSize: 16 }}>
          ⏳ {S.loadingPdf}
        </div>
      )}

      {!pdfDoc && !loading && (
        <div ref={canvasContainerRef} style={{ flex: 1, minHeight: 0, display: "flex", alignItems: "center", justifyContent: "center", background: "#f0ede4", borderRadius: 16, border: "2px dashed #c8d5c0", color: "#aaa", fontSize: 16, flexDirection: "column", gap: 12 }}>
          <span style={{ fontSize: 40 }}>🎼</span>
          <span>{S.noScore}</span>
        </div>
      )}

      {pdfDoc && (
        <div ref={canvasContainerRef} style={{ flex: 1, minHeight: 0, position: "relative", overflow: "auto", borderRadius: 12, border: "2px solid #c8d5c0", background: "#f5f2eb", cursor: tool === "select" ? "grab" : tool === "eraser" ? "cell" : "crosshair" }}>
          <canvas ref={pdfCanvasRef} style={{ display: "block" }} />
          <canvas ref={annotCanvasRef}
            style={{ position: "absolute", top: 0, left: 0, touchAction: "none" }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerLeave={onPointerUp}
            onPointerCancel={onPointerUp}
          />

          {/* Floating toggle button — always visible on score */}
          <button
            onClick={() => setToolbarVisible((v) => !v)}
            title={toolbarVisible ? S.hideTools : S.showTools}
            style={{
              position: "absolute", top: 10, right: 10,
              background: "rgba(26,46,34,0.85)", color: "#e8e4d8",
              border: "1px solid #4a7c59", borderRadius: 20,
              padding: "6px 12px", cursor: "pointer",
              fontSize: 12, fontWeight: 700, backdropFilter: "blur(4px)",
              zIndex: 10,
            }}>
            {toolbarVisible ? "✕ " + S.hideTools : "🛠 " + S.showTools}
          </button>
        </div>
      )}

      {/* ── Recorder ── */}
      <ScoreRecorder lang={lang} />
    </div>
  );
}
